    await upd.dispatchEvent('mouseenter');
    await page.waitForSelector('.long-tip:not([hidden]) .CodeMirror');
    assert.ok(await page.locator('.long-tip .chg-added').count() >= 1);
    assert.match(await page.evaluate(() => document.querySelector('.long-tip .CodeMirror').CodeMirror.getValue()), /A new line from main\./);
    await upd.dispatchEvent('mouseleave');
    const was = page.locator('#tl-detail .tl-code .was', { hasText: 'was "..."' }).first();
    await was.dispatchEvent('mouseenter');
    await page.waitForSelector('.long-tip:not([hidden]) .chg-added');
    await was.dispatchEvent('mouseleave');
    // Files: the tree of all the files on the left; the changed file opens first, with File and Changes tabs
    await page.click('#sv-switches [data-input*="files"]');
    await page.waitForSelector('#tl-detail .kv-tree');
    assert.ok(await page.locator('#tl-detail .kv-tree summary', { hasText: /^docs\/$/ }).count() === 1);
    assert.equal(await page.textContent('#tl-detail .kv-item.on'), 'state-view.md');
    assert.deepEqual(await page.$$eval('#tl-detail .kv-tabs button', els => els.map(x => x.textContent)), ['File', 'Changes']);
    // the file viewer: an md file reads as a page with its contents on the left; Source shows its text
    await page.waitForSelector('#tl-detail .fv.fv-md .md-page');
    assert.match(await page.textContent('#tl-detail .fv .md-page'), /A new line from main\./);
    // with Changes, the read mode of an updated md file shows its changes: the new line is green
    assert.deepEqual(await page.$$eval('#tl-detail .md-page .chg-added', els => els.map(x => x.textContent)), ['A new line from main.']);
    assert.equal(await page.textContent('#tl-detail .fv-badge'), 'MD');
    // the head: the kind, the size and the tokens (no name, no lines), and icon buttons with their names as titles
    assert.match(await page.textContent('#tl-detail .fv-size'), /^[\d.]+ KB · ≈ [\d.]+k? tokens?$/);
    assert.deepEqual(await page.$$eval('#tl-detail .fv-head button', els => els.map(x => [x.title, x.textContent.trim()])),
      [['Read', ''], ['Source', ''], ['Contents', ''], ['Copy', ''], ['Full screen', '']]);
    // Contents is hidden at first; its button shows it, and again hides it
    assert.equal(await page.locator('#tl-detail .fv-side').count(), 0);
    await page.click('#tl-detail .fv-side-btn');
    assert.ok(await page.locator('#tl-detail .fv-side .fv-sym').count() >= 3);
    assert.equal(await page.getAttribute('#tl-detail .fv-side-btn', 'aria-pressed'), 'true');
    await page.click('#tl-detail .fv-seg button[title="Source"]');
    assert.match(await page.locator('#tl-detail .fv .fv-code').evaluate(e => e.cm.getValue()), /A new line from main\./);
    assert.equal(await page.getAttribute('#tl-detail .fv-side-btn', 'title'), 'Functions');
    await page.click('#tl-detail .fv-seg button[title="Read"]');
    await page.waitForSelector('#tl-detail .fv .md-page');
    // md: one Style select with the six themes of the state view; a choice sets state-view ui-data.md_theme and the look of the page
    assert.deepEqual(await page.$$eval('#tl-detail .fv .fv-style option', els => els.map(x => x.value)), ['reader', 'white', 'black', 'sepia', 'night', 'mono']);
    await page.selectOption('#tl-detail .fv .fv-style', 'sepia');
    await page.waitForFunction(() => document.querySelector('#tl-detail .fv-doc').dataset.mdTheme === 'sepia');
    assert.equal(await page.evaluate(() => window.agentOS.state.extension.views['state-view']['ui-data'].md_theme), 'sepia');
    await page.selectOption('#tl-detail .fv .fv-style', 'reader');
    await page.waitForFunction(() => document.querySelector('#tl-detail .fv-doc').dataset.mdTheme === 'reader');
    // Full screen: the file viewer covers the page; Escape gives it back its place
    await page.click('#tl-detail .fv-full-btn');
    await page.waitForSelector('#tl-detail .fv.fv-full');
    assert.deepEqual(await page.$eval('#tl-detail .fv.fv-full', e => { const r = e.getBoundingClientRect(); return [r.left, r.top, r.width, r.height]; }), await page.evaluate(() => [0, 0, innerWidth, innerHeight]));
    await page.keyboard.press('Escape');
    await page.waitForSelector('#tl-detail .fv.fv-full', { state: 'detached' });
    assert.ok(await page.locator('#tl-detail .kv').count() === 1, 'Escape leaves the step open');
    await page.click('#tl-detail .kv-tabs button:has-text("Changes")');
    await page.waitForSelector('#tl-detail .kv-main .tl-files');
    await page.locator('#tl-detail .kv-main .tl-files .tl-file').nth(1).locator('.chg-added').first().waitFor();
    // a file the block did not change has only its File tab
    await page.locator('#tl-detail .kv-item', { hasText: /^index\.html$/ }).click();
    assert.deepEqual(await page.$$eval('#tl-detail .kv-tabs button', els => els.map(x => x.textContent)), ['File']);
    // code has its outline (here the ids and scripts of index.html); a click on it goes to the line; Find marks the matches
    await page.waitForSelector('#tl-detail .fv.fv-html .fv-side .fv-sym');
    assert.ok((await page.$$eval('#tl-detail .fv-sym-name', els => els.map(x => x.textContent))).includes('div#index-view'));
    await page.locator('#tl-detail .fv-sym', { hasText: 'div#index-view' }).first().click();
    await page.fill('#tl-detail .fv-find', 'agentOS');
    assert.match(await page.textContent('#tl-detail .fv-count'), /^\d+ match/);
    await page.press('#tl-detail .fv-find', 'Enter');
    assert.match(await page.textContent('#tl-detail .fv-count'), /^1 of \d+/);
    // a json file is a tree
    await page.locator('#tl-detail .kv-item', { hasText: /^owner-draft\.jsonc$/ }).click();
    await page.waitForSelector('#tl-detail .fv.fv-json .jv-row');
    assert.ok(await page.locator('#tl-detail .jv-key').count() > 3);
    // a function has the tab Pseudo code: its docs, then numbered lines with keywords
    await page.click('#sv-switches [data-input*="functions"]');
    await page.locator('#tl-detail .kv-item', { hasText: /^get-state$/ }).click();
    assert.deepEqual(await page.$$eval('#tl-detail .kv-tabs button', els => els.map(x => x.textContent)), ['Function', 'Pseudo code']);
    await page.click('#tl-detail .kv-tabs button:has-text("Pseudo code")');
    await page.waitForSelector('#tl-detail .fv-pseudo .ps-line');
    assert.equal(await page.locator('#tl-detail .ps-line').count(), 4);
    assert.deepEqual(await page.$$eval('#tl-detail .ps-kw', els => els.map(x => x.textContent)), ['READ', 'IF', 'THROW', 'RETURN']);
    assert.equal(await page.locator('#tl-detail .ps-line').nth(2).locator('.ps-guide').count(), 1);
    assert.match(await page.textContent('#tl-detail .ps-docs'), /Returns the JSON state/);
    await page.click('#sv-switches [data-input*="all"]');
    await page.waitForSelector('#tl-detail .st-legend');
    await page.click('#details');
    await page.waitForSelector('#tl-detail .tl-explain');
    assert.match(await page.textContent('#tl-detail .tl-part'), /git commit 0123456 \(Add a line\)/);
    assert.match(await page.textContent('#tl-detail .tl-explain'), /state-view\.mdIt had no last line\.It has a last line\./);
    const filePart = part('docs/state-view.md');
    assert.match(await filePart.textContent(), /This file was updated/);
    await filePart.locator('.tl-call-head').click();
    await filePart.locator('.tl-files .tl-code').nth(1).waitFor();
    await filePart.locator('.tl-files .tl-code').nth(1).locator('.chg-added').first().waitFor();
    await page.click('#details');

    // a newer version with a new agent run: an Agent run block after its New version block. With no block chosen, the
    // timeline chooses that run (Last agent run, at the left), so the Files view shows the files of the new version
    await page.evaluate(() => {
      const os = window.agentOS, head = os.history.commits[os.history.commits.length - 1];
      const st = JSON.parse(head.state.replace(/^[ \t]*\/\/ shared by all apps[ \t]*$/m, ''));
      const files = st.agents['agent-oss'].files, runs = files.runs, run = JSON.parse(runs[Object.keys(runs).filter(k => /\.json$/.test(k)).sort().pop()]);
      Object.assign(run, { session: 'zzztest', run: 99, started: new Date().toISOString(), ended: new Date().toISOString() });
      runs['zzztest-99.json'] = JSON.stringify(run);
      files['from-the-run.md'] = '# From the run';
      window.__blobs.v5 = JSON.stringify(st, null, 2);
      window.__docs['commits/c000005'] = { n: 5, parent: 4, at: new Date().toISOString(), state_file: 'v5', summary: { added: 2, updated: 0, deleted: 0 },
        paths: ['added agents.agent-oss.files.runs.zzztest-99.json', 'added agents.agent-oss.files.from-the-run.md'], source: { git: 'fedcba9876543210', branch: 'main', message: 'A run', request: 'a run', session: 'https://claude.ai/code/test', explain: [] } };
      window.__listeners.forEach(f => f());
    });
    await page.waitForFunction(() => window.agentOS.history.commits.length === 5);
    await page.evaluate(() => window.agentOS.os.call('extension.views.timeline-view.functions.local.select', { id: null }));
    await page.waitForFunction(() => /session zzz · run 99/.test(document.querySelector('#tl-strip .tl-step.on') && document.querySelector('#tl-strip .tl-step.on').textContent));
    assert.equal(await page.textContent('#tl-strip .tl-step.on .tl-kind'), 'Last agent run');
    assert.equal(await page.locator('#tl-strip .tl-step.on.pin-left, #tl-strip .tl-step.on.pin-right').count(), 1);
    assert.equal(await page.textContent('#tl-strip .tl-step .tl-kind'), 'Agent run');
    assert.match(await page.textContent('#pos'), /^v5 /);
    await page.click('#sv-switches [data-input*="files"]');
    await page.waitForSelector('#tl-detail .kv-tree');
    assert.equal(await page.locator('#tl-detail .kv-item', { hasText: /^from-the-run\.md$/ }).count(), 1);
    await page.click('#sv-switches [data-input*="all"]');

    // every call, with its parent, is in the stored call log
    await page.waitForFunction(() => Object.keys(window.__docs).some(k => k.startsWith('calls/') && window.__docs[k].items.some(i => i.name === 'loadNewerVersion')), null, { timeout: 5000 });
    const log = await page.evaluate(() => Object.entries(window.__docs).find(([k]) => k.startsWith('calls/'))[1]);
    const names = new Set(log.items.map(i => i.name));
    // (the log keeps the newest calls: at most 400, and at most 240 KB; the first ones, like loadState, can be cut)
    assert.ok(names.has('loadState') || log.items.length < log.count, 'loadState, or a log that was cut');
    assert.ok(JSON.stringify(log).length <= 240000);
    // the log is the newest calls of the page, in order, without a gap
    const all = await page.evaluate(() => window.agentOS.calls.map(c => c.id));
    assert.deepEqual(log.items.map(i => i.id), all.slice(all.indexOf(log.items[0].id), all.indexOf(log.items[0].id) + log.items.length));
    for (const n of ['loadNewerVersion', 'extension.functions.render', 'local.refresh']) assert.ok(names.has(n), n);
    assert.ok(log.items.every(i => i.ok && i.at && typeof i.ms === 'number'), JSON.stringify(log.items.filter(i => !i.ok).slice(0, 3)));

    // the Reload button of the timeline: the page loads again, the timeline opens and replays from the first step,
    // the last agent run
    // (the timeline stayed open after the new version)
    assert.equal(await page.isHidden('#timeline-view'), false);
    await Promise.all([page.waitForNavigation(), page.click('#tl-reload')]);
    await page.waitForFunction(() => window.agentOS && window.agentOS.state && window.agentOS.state.extension.views['timeline-view']['ui-data'].playing);
    await page.waitForSelector('#sv-block b');
    // (the replay started at the last agent run)
    assert.deepEqual(await page.evaluate(() => window.agentOS.calls.filter(c => c.name === 'local.select').map(c => c.input.input.id).slice(0, 1).map(id => /^run:runs\//.test(id))), [true]);
    assert.equal((await svd()).timeline_open, true);
    assert.equal(await page.evaluate(() => sessionStorage.getItem('agent-os.timeline-replay')), null);
    // (the first draw of the state view with the 2 MB state takes about 6 s: the replay goes on after it)
    await page.waitForFunction(() => ['runtime', 'open'].includes(window.agentOS.state.extension.views['timeline-view']['ui-data'].selected) || /^Block [3-9]/.test(document.querySelector('#sv-block').textContent), null, { timeout: 15000 });
    // the replay goes on past the blocks that were there when it started (the page was still starting)
    await page.waitForFunction(() => /^Block \d+: Start the page/.test(document.querySelector('#sv-block').textContent), null, { timeout: 8000 });
    assert.deepEqual(errors, []);
  } finally {
    await browser.close();
    server.close();
  }
});

tests.state-core.test.js:
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const core = require('../state-core.js');

const seed = fs.readFileSync(path.join(__dirname, '..', 'state.json'), 'utf8');

test('diff finds added, updated and deleted entries', () => {
  const changes = core.diff({ a: 1, b: { c: 2, d: 3 } }, { a: 1, b: { c: 5 }, e: {} });
  assert.deepEqual(changes, [
    { type: 'updated', path: ['b', 'c'], before: 2, after: 5 },
    { type: 'deleted', path: ['b', 'd'], before: 3 },
    { type: 'added', path: ['e'], after: {} }
  ]);
  assert.deepEqual(core.summarize(changes), { added: 1, updated: 1, deleted: 1 });
});

test('diff of equal states is empty', () => {
  assert.deepEqual(core.diff(JSON.parse(seed), JSON.parse(seed)), []);
});

test('changes view keeps only what changed, with line marks', () => {
  const fixture = { agents: {}, extension: { views: { 'header-view': { 'ui-data': { notifications_button: { pressed: false, count: 2 }, back_button: {} } } }, data: {} } };
  const before = JSON.parse(JSON.stringify(fixture));
  const after = JSON.parse(JSON.stringify(fixture));
  after.extension.views['header-view']['ui-data'].notifications_button.count = 5;
  delete after.extension.views['header-view']['ui-data'].back_button;
  after.extension.data.note = 'hi';
  const v = core.changesView(before, after);
  const parsed = JSON.parse(v.text);
  assert.deepEqual(Object.keys(parsed), ['extension']);
  assert.deepEqual(parsed.extension.views['header-view']['ui-data'], { notifications_button: { count: 5 }, back_button: {} });
  assert.deepEqual(parsed.extension.data, { note: 'hi' });
  assert.deepEqual(v.marks.map(m => [m.type, m.path.join('.')]), [
    ['updated', 'extension.views.header-view.ui-data.notifications_button.count'],
    ['deleted', 'extension.views.header-view.ui-data.back_button'],
    ['added', 'extension.data.note']
  ]);
  const lines = v.text.split('\n');
  v.marks.forEach(m => assert.ok(lines[m.from].includes(JSON.stringify(m.path[m.path.length - 1]))));
  assert.equal(v.marks[0].before, 2);
});

test('changes view of identical states is empty', () => {
  const v = core.changesView({ a: 1 }, { a: 1 });
  assert.equal(v.empty, true);
  assert.equal(v.text, '{}');
});

test('commits chain and record what changed', () => {
  const c1 = core.makeCommit(null, seed, 't1');
  assert.equal(c1.n, 1);
  assert.equal(c1.parent, null);
  assert.equal(c1.summary.added, 4);
  const next = JSON.parse(seed);
  next.extension.views['header-view']['ui-data'].state_button = { pressed: true };
  const c2 = core.makeCommit(c1, JSON.stringify(next, null, 2), 't2');
  assert.equal(c2.n, 2);
  assert.equal(c2.parent, 1);
  assert.deepEqual(c2.summary, { added: 1, updated: 0, deleted: 0 });
  assert.deepEqual(c2.paths, ['added extension.views.header-view.ui-data.state_button']);
  assert.equal(core.commitId(2), 'c000002');
});

test('history steps stay inside the commits and the draft', () => {
  const commits = [core.makeCommit(null, '{"a":1}', 't1')];
  commits.push(core.makeCommit(commits[0], '{"a":2}', 't2'));
  assert.equal(core.step(1, 1, commits, null), 1);
  assert.equal(core.step(1, 1, commits, '{"a":3}'), 2);
  assert.equal(core.step(0, -1, commits, null), 0);
  assert.equal(core.textAt(2, commits, '{"a":3}'), '{"a":3}');
  assert.deepEqual(core.pairAt(0, commits, null), { before: {}, after: { a: 1 } });
  assert.deepEqual(core.pairAt(2, commits, '{"a":3}'), { before: { a: 2 }, after: { a: 3 } });
});

test('tracker records name, input, output, related data and errors', async () => {
  let t = 0;
  const seen = [];
  const tr = core.createTracker({ now: () => 'now', clock: () => (t += 5), onRecord: r => seen.push(r.name) });
  const v = tr.track('save', { size: 3 }, ctx => { ctx.relate({ commit: 2 }); return 'ok'; });
  assert.equal(v, 'ok');
  assert.throws(() => tr.track('bad', null, () => { throw new Error('nope'); }), /nope/);
  await tr.track('later', null, async ctx => { ctx.relate({ pos: 1 }); return 7; });
  assert.deepEqual(tr.records.map(r => [r.id, r.name, r.ok, r.output, r.error, r.related]), [
    [1, 'save', true, 'ok', null, { commit: 2 }],
    [2, 'bad', false, null, 'nope', {}],
    [3, 'later', true, 7, null, { pos: 1 }]
  ]);
  assert.equal(tr.records[0].ms, 5);
  assert.deepEqual(seen, ['save', 'bad', 'later']);
});

test('paths read keys that hold dots', () => {
  const s = { extension: { views: { 'header-view': { functions: { 'local.open.state-view': { code: 'x' } } } } }, files: { 'CLAUDE.md': 1 } };
  assert.equal(core.getPath(s, 'extension.views.header-view.functions.local.open.state-view.code'), 'x');
  assert.equal(core.getPath(s, 'files.CLAUDE.md'), 1);
  assert.equal(core.getPath(s, 'extension.nothing'), undefined);
  core.setPath(s, 'files.CLAUDE.md', 2);
  assert.equal(s.files['CLAUDE.md'], 2);
});

test('runtime fields are left out of comparisons', () => {
  const s = { v: { functions: { 'local.init': { code: '', output: { a: 1 }, performance: { last: 2 }, calls: { f: { input: 'x', output: 3 } }, tests: { t: { input: 1, result: { ok: true } } } } } } };
  assert.deepEqual(core.stripRuntime(s), { v: { functions: { 'local.init': { code: '', calls: { f: { input: 'x' } }, tests: { t: { input: 1 } } } } } });
  assert.equal(s.v.functions['local.init'].output.a, 1);
});

test('templates fill ui-data and escape text', () => {
  assert.equal(core.template('<b>${e(d.name)}</b>${d.n ? `<i>${d.n}</i>` : ""}', { name: '<Slide>', n: 2 }), '<b>&lt;Slide&gt;</b><i>2</i>');
});

test('test expectations report each failure', () => {
  const has = sel => sel === '#a';
  assert.deepEqual(core.checkExpect({ output: { open: true }, 'output-has': ['x'], dom: ['#a'], 'dom-absent': ['#b'] }, { open: true, x: 1 }, has), []);
  assert.deepEqual(core.checkExpect({ output: { open: true }, dom: ['#b'] }, { open: false }, has), ['output.open is false, expected true', 'no element #b']);
});

test('brief keeps logs small', () => {
  assert.deepEqual(core.brief({ a: 1 }), { a: 1 });
  assert.deepEqual(core.brief('x'.repeat(300)), { type: 'text', length: 300 });
  assert.equal(core.brief(undefined), null);
});

test('state.json runs from index-view and every function is complete', () => {
  const s = JSON.parse(seed);
  const views = s.extension.views;
  assert.deepEqual(Object.keys(views), ['index-view', 'header-view', 'docs-view', 'timeline-view', 'state-view', 'recorder-view', 'notes-view']);
  core.walk(s, [], (v, p) => {
    if (p[p.length - 2] !== 'functions') return;
    for (const k of ['input', 'output', 'imports', 'tests', 'expected-state-change', 'docs', 'performance', 'code', 'calls']) assert.ok(k in v, `${p.join('.')} has ${k}`);
    assert.ok(v.docs.length > 10, `${p.join('.')} has docs`);
    // import lines, then the function with its signature; each import is in imports
    assert.match(v.code, /^(import \w+ from '[^']+';\n)*\n?async function [A-Za-z]+\(/, `${p.join('.')} code has a signature`);
    for (const [, name] of v.code.matchAll(/^import \w+ from '([^']+)';$/gm)) assert.ok(name in v.imports, `${p.join('.')} imports ${name}`);
    if (/\bos\./.test(v.code)) assert.match(v.code, /^import os from 'os';$/m, `${p.join('.')} imports os`);
    for (const name of Object.keys(v.calls)) assert.ok(name.startsWith('local.') || core.getPath(s, name), `${name} exists`);
  });
  // each view's html starts with one root element whose id is the view's name
  Object.entries(views).forEach(([name, v]) => assert.match(core.template(v.html, v['ui-data']).trim(), new RegExp('^<[a-z]+ id="' + name + '"')));
});

test('comments are allowed and kept out of the data', () => {
  const text = '{\n  // the header\n  "a": 1, /* inline */ "b": "x // not a comment"\n}';
  assert.deepEqual(core.parseJsonc(text), { a: 1, b: 'x // not a comment' });
  const c = core.makeCommit(null, text, 't');
  assert.equal(c.state, text);
});

test('autofix repairs the owner draft and keeps its comment', () => {
  const draft = fs.readFileSync(path.join(__dirname, 'fixtures', 'owner-draft.jsonc'), 'utf8');
  assert.throws(() => core.parseJsonc(draft));
  const fixed = core.autofix(draft);
  const s = core.parseJsonc(fixed);
  assert.ok(fixed.includes('// last minimum and maximum'));
  assert.deepEqual(Object.keys(s.extension), ['views', 'functions', 'data', 'common_app_storage', 'apps']);
  assert.deepEqual(Object.keys(s.extension.views), ['index-view', 'header-view', 'state-view']);
  assert.equal(s.extension.views['header-view'].functions['local.init'].code, '');
});

test('autofix handles other common slips', () => {
  assert.deepEqual(core.parseJsonc(core.autofix("{a: 'x', b: [1 2,], c: True,}")), { a: 'x', b: [1, 2], c: true });
  assert.deepEqual(core.parseJsonc(core.autofix('{"a": {"b": 1')), { a: { b: 1 } });
  assert.equal(core.autofix('{"a": 1}'), '{"a": 1}');
});

test('patching text keeps comments and layout', () => {
  const text = '{\n  // views\n  "a": {"x": 1},\n  "b": {},\n  "c": 2 // two\n}';
  const target = { a: { x: 5, y: true }, b: { k: 'v' } };
  const out = core.patchText(text, target);
  assert.deepEqual(core.parseJsonc(out.text), target);
  assert.ok(out.text.includes('// views'));
  assert.equal(out.edits.length, 4);
  let t = text;
  out.edits.forEach(e => { t = t.slice(0, e.from) + e.insert + t.slice(e.to); });
  assert.equal(t, out.text);
});

test('pathAt names the entry under the cursor', () => {
  const text = '{\n  "extension": {\n    "views": {\n      "state-view": { "html": "<b>" }\n    }\n  }\n}';
  assert.deepEqual(core.pathAt(text, text.indexOf('<b>')), ['extension', 'views', 'state-view', 'html']);
  assert.deepEqual(core.pathAt(text, text.indexOf('"state-view"') + 2), ['extension', 'views', 'state-view']);
});

test('ago and state expectations', () => {
  assert.equal(core.ago('2026-10-25T12:00:00Z', Date.parse('2026-10-25T12:05:00Z')), '5 min ago');
  const fails = core.checkExpect({ state: { 'a.b': 1 }, 'state-changed': ['a.c'] }, {}, () => false, { get: p => (p === 'a.b' ? 2 : undefined), changed: ['a.d'] });
  assert.deepEqual(fails, ['a.b is 2, expected 1', 'a.c did not change']);
});

test('each run is checked against expected-state-change', () => {
  const before = { v: { ui: { open: false, pos: 3, n: 1 } } };
  const after = { v: { ui: { open: true, pos: 2, n: 1 }, extra: 1 } };
  assert.deepEqual(core.checkStateChange({ 'v.ui.open': 'toggles', 'v.ui.pos': 'input' }, before, after, 2), ['unexpected change: added v.extra']);
  assert.deepEqual(core.checkStateChange({ 'v.ui.n': 'changes', '*': 'may change' }, before, after), ['v.ui.n did not change']);
  assert.deepEqual(core.checkStateChange({}, before, before), []);
  assert.deepEqual(core.checkStateChange({ 'v.ui.pos': 'input.to' }, before, after, { to: 2 }, ['v.extra', 'v.ui.open']), []);
  assert.deepEqual(core.checkStateChange({ 'v.ui.pos': 'input.to' }, before, after, { to: 5 }, ['v.extra', 'v.ui.open']), ['v.ui.pos is 2, expected input.to 5']);
  // changes made by nested calls are theirs, not the caller's
  assert.deepEqual(core.checkStateChange({ 'v.ui.open': 'toggles', 'v.ui.pos': 'input' }, before, after, 2, ['v.extra']), []);
});

test('markdown parts give the same text back, and lines know their kind', () => {
  const docs = JSON.parse(seed).agents['agent-oss'].files.docs;
  for (const [name, text] of Object.entries(docs)) assert.equal(core.mdText(core.mdParse(text)), text, name);
  const parts = core.mdParse('# T\n\n## S\n- a\n2. b\ntext\n```js\nx()\n```\n```svg<svg></svg>```');
  assert.deepEqual(parts.map(p => p.kind), ['lines', 'code', 'lines', 'svg', 'lines']);
  assert.equal(parts[1].text, 'x()');
  assert.deepEqual(['# T', '## S', '- a', '2. b', 'text', ''].map(l => core.mdLine(l).type), ['h1', 'h2', 'item', 'step', 'p', 'blank']);
  assert.deepEqual(core.mdLine('12. go'), { mark: '12. ', text: 'go', type: 'step' });
});


test('filterLines shows one kind only, and can hide empty values', () => {
  const text = JSON.stringify({ agents: { a: { files: { 'x.md': 'hi' }, connection: {} } }, extension: { views: { v: { html: '' } }, functions: { f: {} } } }, null, 2);
  const lines = text.split('\n'), shown = hidden => lines.filter((l, i) => !hidden.some(([a, b]) => i >= a && i <= b)).join('\n');
  // only files: the files and the objects around them
  let s = shown(core.filterLines(text, null, '', 'files'));
  assert.match(s, /"x\.md"/);
  assert.doesNotMatch(s, /"extension"|"connection"/);
  // all: nothing hidden
  assert.deepEqual(core.filterLines(text, null, '', 'all'), []);
  // a kind and a text together: the text inside that kind
  s = shown(core.filterLines(text, null, 'views', 'views'));
  assert.match(s, /"html"/);
  assert.doesNotMatch(s, /"agents"/);
  // empty values hide: {}, "" (the html), and the object of f
  s = shown(core.filterLines(text, null, '', 'all', { hideEmpty: true }));
  assert.doesNotMatch(s, /"connection"|"html"|"f"/);
  assert.match(s, /"x\.md"/);
  // (lines hidden only for an empty value say so: they hide without a mark)
  assert.ok(core.filterLines(text, null, '', 'all', { hideEmpty: true }).every(r => r[2] === 'empty'));
  // with a text, the lines the text hides keep their mark
  const both = core.filterLines(text, null, 'x.md', 'all', { hideEmpty: true });
  assert.ok(both.some(r => r[2] === 'empty') || both.every(r => r.length === 2));
  assert.ok(both.some(r => r.length === 2));
});

test('a text of only {} or [] is empty: Show empty off hides it, the editor shows it grey', () => {
  assert.equal(core.emptyText('"{}\\n"'), true);
  assert.equal(core.emptyText('"[ ]"'), true);
  assert.equal(core.emptyText('"{}\\nx"'), false);
  assert.equal(core.emptyText('""'), false);
  const text = JSON.stringify({ a: { 's.json': '{}\n', 'b.json': '{"x":1}\n' } }, null, 2);
  assert.deepEqual(core.filterLines(text, null, '', {}, { hideEmpty: true }), [[2, 2, 'empty']]);
});

