      }
    }
    const modes = fk.kind === 'md' ? ['Read', 'Source'] : fk.kind === 'json' && parsed !== undefined ? ['Tree', 'Source'] : [];
    const seg = el('div', 'fv-seg');
    const mode = () => modes.includes(R.fileMode[fk.kind]) ? R.fileMode[fk.kind] : modes[0];
    modes.forEach(m => {
